/* MIT. Reuses the existing merchant and atlas; no extra NPC/texture allocation. */
static void merchant_draw(const Combat*g,const MerchantUI*u){
 if(u->mode==MS_STYLES){ui_panel(100,72,440,332,"Cart Stylist - test service",1,-1);ui_scaled(112,100,.9f,"All five styles | Free | Rented Merchant cart required");for(int i=0;i<5;i++){int yy=139+i*32;ui_cell(110,yy-2,420,26,i==u->item);ui_text(120,yy,"Style %d%s",i+1,g->cartOwned&&g->cartStyle==i?" (current)":"");}ui_hint64(112,310,.85f,"Up/down: choose | A: apply | B: leave");ui_scaled(112,337,.8f,"Prototype access bypasses Change Cart level/SP checks.");ui_scaled(112,370,.75f,"%.80s",g->log);return;}
 if(u->mode==MS_BUY||u->mode==MS_SELL){hud_shop(g,u->item,u->mode==MS_SELL,u->quantity);return;}
 ui_panel(100,58,440,370,u->mode==MS_STORAGE?"Local item storage":"Merchant & local services (prototype)",1,-1);
 if(u->mode==MS_STORAGE)ui_scaled(112,82,.85f,"%d Zeny | Bag %lld/%d | Access paid",g->zeny,(long long)(inventory_weight(g)/10),inventory_weight_max(g)/10);else ui_scaled(112,82,.85f,"%d Zeny | Bag %lld/%d | Cart %lld/8000",g->zeny,(long long)(inventory_weight(g)/10),inventory_weight_max(g)/10,(long long)(inventory_cart_weight(g)/10));
 if(u->mode==MS_STORAGE){int start=u->item/8*8;for(int i=start;i<ITEM_COUNT*2&&i<start+8;i++){int y=112+(i-start)*25,item=i%ITEM_COUNT,take=i>=ITEM_COUNT;ui_cell(110,y-2,420,23,i==u->item);ui_scaled(118,y,.8f,"%s %.20s | Bag %d / Stored %d",take?"Take":"Store",itemDefs[item].name,inventory_count(g,item),inventory_box_count52(g,2,item));}ui_hint64(112,347,.85f,"L/R: quantity %d | A: transfer | B: services",u->quantity);ui_scaled(112,322,.8f,"Rows %d-%d of %d",start+1,start+8<ITEM_COUNT*2?start+8:ITEM_COUNT*2,ITEM_COUNT*2);}
 else if(u->mode==MS_CART){int start=u->item/8*8;for(int i=start;i<ITEM_COUNT*2&&i<start+8;i++){int y=112+(i-start)*25,item=i%ITEM_COUNT,take=i>=ITEM_COUNT;ui_cell(110,y-2,420,23,i==u->item);ui_scaled(118,y,.9f,"%s %.20s: %d",take?"Take":"Store",itemDefs[item].name,take?inventory_box_count52(g,1,item):inventory_count(g,item));}ui_hint64(112,347,.85f,"L/R: quantity %d | A: transfer | B: services",u->quantity);}
 else{static const char*rows[MS_ROWS]={"Buy supplies","Sell items","Rent cart - 800 Zeny","Manage cart","Return EMPTY cart - no refund","Recovery - 100 Zeny (prototype)","Bind home here - free","Local storage - 50 Zeny access","Repair damaged weapon - 5000 Zeny","Leave"};for(int first=u->choice/8*8,i=first;i<MS_ROWS&&i<first+8;i++){int y=112+(i-first)*25;ui_cell(110,y-2,420,23,i==u->choice);ui_scaled(118,y,.9f,"%s",rows[i]);}ui_hint64(112,347,.85f,"%s",u->confirm?"A again: confirm service | B: cancel":"Up/down: choose | A: enter | B: leave");}
 ui_scaled(112,372,.7f,"All jobs | Storage:30000 per item | Remove equipped gear before storing.");ui_scaled(112,402,.7f,"%.85s",g->log);
}
